//! tachyon-hostd: the privileged agent on each host. It keeps paused
//! microVMs warm, forks job disks copy-on-write, runs each job in a jailed
//! Cloud Hypervisor VM, and talks to the Go control plane over hostlink.v1.
//!
//! Configuration is by environment variable (see README).

pub mod baseimage;
pub mod cpustat;
pub mod hypervisor;
pub mod jailer;
pub mod lifecycle;
pub mod link;
pub mod network;
pub mod outbox;
pub mod prefork;
pub mod recovery;
pub mod replicate;
pub mod rootfs;
pub mod storage;
pub mod telemetry;
pub mod tls;
pub mod usage;

// Generated by tonic-build; not held to our lint bar.
#[allow(clippy::all, clippy::pedantic)]
pub mod pb {
    tonic::include_proto!("tachyon.hostlink.v1");
}

use anyhow::{Context, Result};
use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::atomic::AtomicU32;
use std::sync::Arc;

fn env(key: &str) -> Result<String> {
    std::env::var(key).with_context(|| format!("{key} is required"))
}

fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

/// Parses "2:2,4:2,8:1" (vcpu:count).
fn parse_warm(s: &str) -> Result<HashMap<u32, usize>> {
    let mut m = HashMap::new();
    for part in s.split(',').filter(|p| !p.is_empty()) {
        let (v, n) = part
            .split_once(':')
            .with_context(|| format!("bad warm entry {part:?}"))?;
        m.insert(v.trim().parse()?, n.trim().parse()?);
    }
    Ok(m)
}

/// Parses "10.0.0.2,10.0.0.3".
fn parse_ips(s: &str) -> Result<Vec<std::net::Ipv4Addr>> {
    s.split(',')
        .map(str::trim)
        .filter(|p| !p.is_empty())
        .map(|p| p.parse().with_context(|| format!("bad IPv4 address {p:?}")))
        .collect()
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .json()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env().unwrap_or_else(|_| "info".into()),
        )
        .init();

    if !cfg!(target_os = "linux") {
        anyhow::bail!(
            "tachyon-hostd runs on Linux hosts with KVM; use `cargo test` for development"
        );
    }

    let args: Vec<String> = std::env::args().collect();
    if args.get(1).map(String::as_str) == Some("prepare-image") {
        let image = args
            .get(2)
            .context("usage: tachyon-hostd prepare-image <name@version>")?;
        return prepare_image(image);
    }

    let info = link::HostInfo {
        host_id: env("TACHYON_HOST_ID")?,
        region: env("TACHYON_REGION")?,
        failure_domain: env_or("TACHYON_FAILURE_DOMAIN", "default"),
        arch: env_or("TACHYON_ARCH", "x86_64"),
        vcpu: env("TACHYON_VCPU")?.parse()?,
        memory_gb: env("TACHYON_MEMORY_GB")?.parse()?,
        peer_address: env_or("TACHYON_PEER_ADDRESS", ""),
        host_group: env_or("TACHYON_HOST_GROUP", ""),
    };
    let run_dir: PathBuf = env_or("TACHYON_RUN_DIR", "/run/tachyon/vms").into();
    let net = network::HostNetwork {
        config: network::NetConfig {
            egress_mbit: env_or("TACHYON_EGRESS_MBIT", "1000").parse()?,
            mirrors: network::parse_list(&env_or("TACHYON_MIRRORS", ""))?,
            dns: parse_ips(&env_or("TACHYON_DNS", ""))?,
        },
        rules_dir: run_dir.join("net"),
        runner: Box::new(storage::ExecRunner),
        resolver: Box::new(network::SystemResolver),
    };
    net.init_host()?;
    let hv = hypervisor::CloudHypervisor {
        binary: env_or("TACHYON_CH_BINARY", "/usr/local/bin/cloud-hypervisor").into(),
        ch_remote: env_or("TACHYON_CH_REMOTE", "/usr/local/bin/ch-remote").into(),
        run_dir,
        snapshots: snapshot_source()?,
        cgroup_parent: env_or("TACHYON_CGROUP", "/sys/fs/cgroup/tachyon").into(),
        base_uid: env_or("TACHYON_BASE_UID", "100000").parse()?,
        next_slot: AtomicU32::new(0),
        net,
    };
    let pool = env("TACHYON_ZFS_POOL")?;
    let repl = replicate::Replicators {
        volumes: Arc::new(replicate::ZfsReplicator {
            pool: pool.clone(),
            runner: storage::ExecRunner,
            spawner: replicate::ExecSpawner,
        }),
        images: Arc::new(replicate::FileImages {
            dir: env_or("TACHYON_IMAGES_DIR", "/var/lib/tachyon/images").into(),
        }),
    };
    let storage = storage::Zfs {
        pool,
        runner: storage::ExecRunner,
    };
    let warm = parse_warm(&env_or("TACHYON_WARM", "2:2,4:2,8:1"))?;
    let outbox = Arc::new(outbox::Outbox::open(
        env_or("TACHYON_STATE_DIR", "/var/lib/tachyon/hostd").as_ref(),
    )?);

    let agent = Arc::new(lifecycle::Agent::new(hv, storage, warm));
    let images_root = std::env::var("TACHYON_IMAGES").ok().map(PathBuf::from);
    // Before Link::new, which creates the instruments on the global meter.
    let meter_provider = telemetry::init_otlp(&info)?;
    let serve_peers = !info.peer_address.is_empty();
    let agent_for_images = agent.clone();
    let mut link = link::Link::new(agent.clone(), info, env("TACHYON_CONTROL_PLANE")?);
    link.outbox = outbox.clone();
    tokio::task::spawn_blocking({
        let (agent, inv) = (agent.clone(), link.inventory.clone());
        move || recover(&agent, &inv, &outbox)
    })
    .await?;
    // A version whose snapshots fail to restore is logged by refill_pool
    // and must not keep the host from serving jobs on other versions.
    let _ = tokio::task::spawn_blocking(move || agent.refill_pool()).await?;
    // Base image files on disk, so rollouts can seed from this host. Not
    // with a versioned store: the control plane reads every base-image ref
    // as "this host can run it", which only prepared versions (reported by
    // `maintain_images`) satisfy.
    if images_root.is_none() {
        for r in replicate::image_refs(repl.images.as_ref())? {
            link.inventory.put(r);
        }
    }
    let peer = Arc::new(link::Peer {
        grants: Arc::default(),
        repl,
        opts: replicate::PullOptions::default(),
    });
    if serve_peers {
        // Pulls are authorized per transfer by control-plane grants.
        // TODO: mTLS between hosts, alongside the hostlink mTLS TODO.
        let listen: std::net::SocketAddr = env_or("TACHYON_PEER_LISTEN", "0.0.0.0:7443").parse()?;
        let svc = pb::peer_snapshot_service_server::PeerSnapshotServiceServer::new(
            replicate::PeerServer {
                grants: peer.grants.clone(),
                repl: peer.repl.clone(),
            },
        );
        tokio::spawn(async move {
            if let Err(e) = tonic::transport::Server::builder()
                .add_service(svc)
                .serve(listen)
                .await
            {
                tracing::error!(error = %e, "peer snapshot service stopped");
            }
        });
    }
    link.peer = Some(peer);
    if let Some(root) = images_root {
        // Report prepared base images so the control plane's rollout knows
        // which versions this host can run, and keep that current as
        // versions are prepared or removed.
        let keep = std::env::var("TACHYON_IMAGES_KEEP")
            .ok()
            .map(|k| k.parse::<usize>())
            .transpose()
            .context("TACHYON_IMAGES_KEEP")?;
        tokio::spawn(maintain_images(
            agent_for_images,
            link.inventory.clone(),
            root,
            keep,
        ));
    }
    let tls = tls::TlsFiles::from_env(|k| std::env::var(k).ok())?;
    if tls.is_none() {
        tracing::warn!("hostlink running WITHOUT mTLS (TACHYON_HOSTLINK_INSECURE)");
    }
    link.tls = tls;
    tokio::select! {
        _ = link.run() => {}
        _ = tokio::signal::ctrl_c() => tracing::info!("shutting down; the next start reaps running VMs and reports their jobs as infra errors"),
    }
    if let Some(mp) = meter_provider {
        // Shutdown blocks on the export task; keep it off the async workers.
        if let Ok(Err(e)) = tokio::task::spawn_blocking(move || mp.shutdown()).await {
            tracing::warn!(error = %e, "flush metrics");
        }
    }
    Ok(())
}

/// Where VMs restore base snapshots from. With TACHYON_IMAGES set, each
/// job restores from the image version it is assigned, and a version that
/// has not been prepared on this host is refused. Without it, the single
/// static directory TACHYON_BASE_SNAPSHOTS (`<dir>/<vcpu>/`) serves every
/// job; TACHYON_BASE_IMAGE=name@version additionally pins which image that
/// directory holds, so jobs for any other version are refused.
fn snapshot_source() -> Result<baseimage::SnapshotSource> {
    snapshot_source_from(|k| std::env::var(k).ok())
}

fn snapshot_source_from(get: impl Fn(&str) -> Option<String>) -> Result<baseimage::SnapshotSource> {
    if let Some(root) = get("TACHYON_IMAGES") {
        if get("TACHYON_BASE_SNAPSHOTS").is_some() {
            tracing::warn!("TACHYON_BASE_SNAPSHOTS is ignored while TACHYON_IMAGES is set");
        }
        return Ok(baseimage::SnapshotSource::Store(root.into()));
    }
    let dir = get("TACHYON_BASE_SNAPSHOTS").context(
        "TACHYON_IMAGES (versioned images) or TACHYON_BASE_SNAPSHOTS (one image) is required",
    )?;
    let image = get("TACHYON_BASE_IMAGE");
    if let Some(i) = &image {
        baseimage::check_ref(i).context("TACHYON_BASE_IMAGE")?;
    }
    Ok(baseimage::SnapshotSource::Static {
        dir: dir.into(),
        image,
    })
}

type HostAgent = lifecycle::Agent<hypervisor::CloudHypervisor, storage::Zfs<storage::ExecRunner>>;

/// Every minute: reports the ready image versions in heartbeats (adding
/// new ones, dropping removed ones), warms VMs for a newly prepared
/// version, and, if `keep` is set, deletes old versions nothing uses.
async fn maintain_images(
    agent: Arc<HostAgent>,
    inv: Arc<link::Inventory>,
    root: PathBuf,
    keep: Option<usize>,
) {
    let mut reported: std::collections::HashSet<String> = Default::default();
    let mut tick = tokio::time::interval(std::time::Duration::from_secs(60));
    loop {
        tick.tick().await;
        let (agent, inv, root, before) =
            (agent.clone(), inv.clone(), root.clone(), reported.clone());
        let res = tokio::task::spawn_blocking(move || {
            let store = baseimage::ImageStore::new(root);
            if let Some(k) = keep {
                match agent.gc_images(&store, k) {
                    Ok(removed) if !removed.is_empty() => {
                        tracing::info!(?removed, "removed old base images");
                    }
                    Ok(_) => {}
                    Err(e) => tracing::warn!(error = %format!("{e:#}"), "base image gc"),
                }
            }
            let ready: std::collections::HashSet<String> = store.ready().into_iter().collect();
            for r in store.snapshot_refs() {
                inv.put(r);
            }
            for gone in before.difference(&ready) {
                inv.remove(pb::snapshot_ref::Kind::BaseImage, gone);
            }
            // Warm VMs for a newly prepared version; failures are logged
            // inside.
            let _ = agent.refill_pool();
            ready
        })
        .await;
        match res {
            Ok(ready) => reported = ready,
            Err(e) => tracing::warn!(error = %e, "base image maintenance"),
        }
    }
}

/// Verifies a base image in TACHYON_IMAGES and builds its per-size paused
/// snapshots (see baseimage.rs).
fn prepare_image(image: &str) -> Result<()> {
    let mut store = baseimage::ImageStore::new(PathBuf::from(env("TACHYON_IMAGES")?));
    store.default_kernel = std::env::var("TACHYON_GUEST_KERNEL").ok().map(Into::into);
    if let Ok(c) = std::env::var("TACHYON_GUEST_CMDLINE") {
        store.cmdline = c;
    }
    let trust = std::fs::read_to_string(env("TACHYON_IMAGE_TRUST")?)?;
    let trusted = baseimage::parse_public_keys(&trust)?;
    let builder = baseimage::ChSnapshotBuilder {
        binary: env_or("TACHYON_CH_BINARY", "/usr/local/bin/cloud-hypervisor").into(),
        ch_remote: env_or("TACHYON_CH_REMOTE", "/usr/local/bin/ch-remote").into(),
        work_dir: env_or("TACHYON_RUN_DIR", "/run/tachyon/vms").into(),
        cgroup_parent: env_or("TACHYON_CGROUP", "/sys/fs/cgroup/tachyon").into(),
        // One below the first VM slot's IDs, so it never collides with a job VM.
        uid: env_or("TACHYON_BASE_UID", "100000").parse::<u32>()? - 1,
        gid: env_or("TACHYON_BASE_UID", "100000").parse::<u32>()? - 1,
        ready_timeout: std::time::Duration::from_secs(300),
    };
    let built = store.prepare(image, &trusted, &builder)?;
    tracing::info!(image, ?built, "base image prepared");
    Ok(())
}

/// Startup recovery (see `recovery`). Each step logs and carries on: a
/// failed cleanup must not keep the host from serving jobs.
fn recover<S: storage::Storage>(
    agent: &lifecycle::Agent<hypervisor::CloudHypervisor, S>,
    inv: &link::Inventory,
    outbox: &outbox::Outbox,
) {
    let lost = recovery::report_interrupted(outbox);
    let vms = recovery::reap_vms(&agent.hv.run_dir, &agent.hv.cgroup_parent);
    let links = agent.hv.net.reap().unwrap_or_else(|e| {
        tracing::warn!(error = %format!("{e:#}"), "remove orphaned VM namespaces");
        Vec::new()
    });
    let disks = recovery::clean_job_disks(&agent.storage).unwrap_or_else(|e| {
        tracing::warn!(error = %format!("{e:#}"), "clean orphaned job disks");
        Vec::new()
    });
    let snapshots = recovery::rebuild_inventory(&agent.storage, inv).unwrap_or_else(|e| {
        tracing::warn!(error = %format!("{e:#}"), "rebuild snapshot inventory");
        0
    });
    tracing::info!(
        interrupted_jobs = lost.len(),
        orphaned_vms = vms.len(),
        orphaned_links = links.len(),
        orphaned_disks = disks.len(),
        snapshots,
        unacked = outbox.len(),
        "recovered host state"
    );
}

#[cfg(test)]
mod tests {
    #[test]
    fn parse_warm() {
        let m = super::parse_warm("2:2, 8:1").unwrap();
        assert_eq!(m[&2], 2);
        assert_eq!(m[&8], 1);
        assert!(super::parse_warm("2-2").is_err());
    }

    #[test]
    fn snapshot_source_selection() {
        use super::baseimage::SnapshotSource;
        let env = |pairs: &'static [(&'static str, &'static str)]| {
            move |k: &str| {
                pairs
                    .iter()
                    .find(|(n, _)| *n == k)
                    .map(|(_, v)| (*v).to_string())
            }
        };
        assert_eq!(
            super::snapshot_source_from(env(&[("TACHYON_IMAGES", "/img")])).unwrap(),
            SnapshotSource::Store("/img".into())
        );
        // The store wins over the static directory.
        assert!(matches!(
            super::snapshot_source_from(env(&[
                ("TACHYON_IMAGES", "/img"),
                ("TACHYON_BASE_SNAPSHOTS", "/snap")
            ]))
            .unwrap(),
            SnapshotSource::Store(_)
        ));
        assert_eq!(
            super::snapshot_source_from(env(&[("TACHYON_BASE_SNAPSHOTS", "/snap")])).unwrap(),
            SnapshotSource::Static {
                dir: "/snap".into(),
                image: None
            }
        );
        assert!(super::snapshot_source_from(env(&[
            ("TACHYON_BASE_SNAPSHOTS", "/snap"),
            ("TACHYON_BASE_IMAGE", "../evil")
        ]))
        .is_err());
        assert!(super::snapshot_source_from(env(&[])).is_err());
    }

    #[test]
    fn parse_ips() {
        assert_eq!(super::parse_ips(" 10.0.0.2, ").unwrap().len(), 1);
        assert!(super::parse_ips("").unwrap().is_empty());
        assert!(super::parse_ips("dns.local").is_err());
    }
}
